package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcDiagnosisCasesTest extends JdbcInviteDiagnosisPoliciesTest {
 DiagnosisServicePolicies servicePolicy;DiagnosisCases cases;OperatorActor handlerA,handlerB,manager;
 @BeforeEach void cases(){for(String table:List.of("notification","diagnosis_notification_target","diagnosis_notification_outbox","diagnosis_case_event","diagnosis_message","diagnosis_case","diagnosis_service_policy","vehicle"))jdbc.update("DELETE FROM "+table);jdbc.execute("DROP TRIGGER IF EXISTS fail_diagnosis_event");jdbc.update("UPDATE operator_account SET can_diagnose_manage=1 WHERE id=1");
  for(int i=1001;i<=1003;i++)jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_diagnose,can_diagnose_manage) VALUES(?,?, 'unused',?,?,?)",i,"synthetic-diagnosis-"+i,"1380000"+i,i==1003?0:1,i==1003?1:0);
  handlerA=op(1001);handlerB=op(1002);manager=op(1003);jdbc.update("INSERT INTO vehicle(id,user_id,plate_no) VALUES(901,1,'synth-owner'),(902,2,'synth-peer')");var ops=new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource()));servicePolicy=new DiagnosisServicePolicies(db,ops);cases=new DiagnosisCases(db,servicePolicy,diagnosis);
 }
 @AfterEach void diagnosisCleanup(){jdbc.execute("DROP TRIGGER IF EXISTS fail_diagnosis_event");}
 OperatorActor op(long id){return new OperatorActor(id,session(id,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(3600));}
 ObjectNode config(String mode){return json.createObjectNode().put("mode",mode).put("source_note","已确认的合成受理来源").put("valid_from",clock.value.minusSeconds(60).toString()).put("valid_to",clock.value.plusSeconds(3600).toString());}
 long configure(String mode){long id=servicePolicy.save(operator,null,key(),config(mode)).path("data").path("id").asLong();servicePolicy.status(operator,id,key(),statusBody(1,"PUBLISHED"));return id;}
 void eligible(){long id=rule(1);enable(id);qualify(promo("user"),"VERIFIED_WECHAT",801);}
 ObjectNode question(long policy){return json.createObjectNode().put("vehicle_id",901).put("policy_id",policy).put("policy_revision",2).put("message","本次主动提交的车辆问题").put("consent",true);}
 long submit(long policy){return cases.create(owner,key(),question(policy)).path("data").path("case_id").asLong();}
 ObjectNode assign(long revision,long operator){return json.createObjectNode().put("expected_revision",revision).put("operator_id",operator);}
 ObjectNode text(long revision,String body){return json.createObjectNode().put("expected_revision",revision).put("message",body);}
 ObjectNode follow(long revision,long policy){return text(revision,"补充问题").put("policy_id",policy).put("policy_revision",2).put("consent",true);}
 @Test void independentPrivilegesAndUnknownConfigurationCannotOpenService(){
  assertEquals("UNKNOWN",servicePolicy.current(owner).get("state"));assertEquals(403,code(()->servicePolicy.list(handlerA,1)));assertEquals(403,code(()->cases.list(operator,false,1)));assertEquals(403,code(()->cases.list(handlerA,true,1)));eligible();assertEquals(false,diagnosis.current(owner).get("service_available"));assertEquals(409,code(()->cases.create(owner,key(),question(1))));assertEquals(0,count("diagnosis_case"));
 }
 @Test void availableOfflinePausedAndMissingHandlersAreRechecked(){
  eligible();long p=configure("AVAILABLE");assertEquals(true,diagnosis.current(owner).get("service_available"));assertEquals("AVAILABLE",servicePolicy.current(owner).get("state"));servicePolicy.status(operator,p,key(),statusBody(2,"STOPPED"));p=configure("LEAVE_MESSAGE");assertEquals(true,diagnosis.current(owner).get("service_available"));submit(p);jdbc.update("UPDATE operator_account SET can_diagnose=0");assertEquals("SOURCE_UNAVAILABLE",servicePolicy.current(owner).get("state"));long source=p;assertEquals(409,code(()->cases.create(owner,key(),question(source))));servicePolicy.status(operator,p,key(),statusBody(2,"STOPPED"));long paused=configure("PAUSED");assertEquals("PAUSED",servicePolicy.current(owner).get("state"));assertEquals(409,code(()->cases.create(owner,key(),question(paused))));
 }
 @Test void createPersistsOnlyChosenTextAndModelsAndHasDurableIntent(){
  eligible();long p=configure("AVAILABLE");String k=key();var b=question(p);var first=cases.create(owner,k,b);long id=first.path("data").path("case_id").asLong();assertEquals(first,cases.create(owner,k,b));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY)");cases.create(owner,k,b);assertEquals(1,count("diagnosis_case"));assertEquals(1,count("diagnosis_message"));assertEquals(1,count("diagnosis_case_event"));assertEquals(400,code(()->cases.create(owner,k,question(p).put("message","different"))));
  var detail=db.mapper.valueToTree(cases.detail(owner,id,1));assertEquals("本次主动提交的车辆问题",detail.path("messages").path("items").get(0).path("body").asText());for(String privateKey:List.of("owner_id","vehicle_id","sender_id","openid","plate_no","vin","source_reference"))assertFalse(detail.toString().contains("\""+privateKey+"\""));assertFalse(jdbc.queryForObject("SELECT after_state FROM audit_log WHERE action='DIAGNOSIS_CREATE'",String.class).contains("本次主动"));assertTrue(jdbc.queryForObject("SELECT admission_snapshot FROM diagnosis_case WHERE id=?",String.class,id).contains("R6B_DIAGNOSIS_V1"));
 }
 @Test void wrongVehicleFalseConsentAndForgedCallerEvidenceAreRejected(){
  eligible();long p=configure("AVAILABLE");assertEquals(404,code(()->cases.create(peer,key(),question(p))));assertEquals(404,code(()->cases.create(owner,key(),question(p).put("vehicle_id",902))));for(String raw:List.of(question(p).put("eligible",true).toString(),question(p).put("consent",false).toString(),question(p).put("operator_id",1001).toString(),question(p)+"{}"))assertThrows(Exception.class,()->DiagnosisCases.input(raw,"create"));assertEquals(0,count("diagnosis_message"));
 }
 @Test void managerCannotReadBodyAndHandlersNeedCurrentAssignment(){
  eligible();long id=submit(configure("AVAILABLE"));assertEquals(404,code(()->cases.detail(handlerA,id,1)));assertEquals(403,code(()->cases.detail(manager,id,1)));assertEquals(403,code(()->cases.detail(operator,id,1)));String queue=db.json(cases.list(manager,true,1));assertFalse(queue.contains("body"));assertFalse(queue.contains("vehicle"));assertFalse(queue.contains("本次主动"));cases.assign(manager,id,key(),assign(1,1001));assertEquals(1L,((Map<?,?>)cases.detail(handlerA,id,1).get("messages")).get("total"));assertEquals(404,code(()->cases.detail(handlerB,id,1)));assertEquals(404,code(()->cases.detail(peer,id,1)));
 }
 @Test void assignmentReplyFollowupTransferAndCloseUseCasAndCurrentPermission(){
  eligible();long p=configure("LEAVE_MESSAGE"),id=submit(p);cases.assign(manager,id,key(),assign(1,1001));String k=key();var reply=text(2,"已核对，本次答复");cases.write(handlerA,id,"reply",k,reply);assertEquals(409,code(()->cases.write(handlerA,id,"reply",key(),reply)));cases.write(owner,id,"message",key(),follow(3,p));cases.assign(manager,id,key(),assign(4,1002));assertEquals(404,code(()->cases.detail(handlerA,id,1)));assertEquals(404,code(()->cases.write(handlerA,id,"reply",k,reply)));cases.write(handlerB,id,"reply",key(),text(5,"新的答复"));cases.write(owner,id,"close",key(),json.createObjectNode().put("expected_revision",6));assertEquals(409,code(()->cases.write(handlerB,id,"reply",key(),text(7,"禁止关闭后回复"))));assertEquals(7,count("diagnosis_case_event"));assertEquals(4,count("diagnosis_message"));
 }
 @Test void expiryAndMonthAffectNewMessagesButNeverEraseOwnHistoricalReply(){
  clock.value=Instant.parse("2026-10-31T15:59:59Z");eligible();long p=configure("AVAILABLE"),id=submit(p);cases.assign(manager,id,key(),assign(1,1001));clock.value=clock.value.plusSeconds(1);assertEquals(409,code(()->cases.create(owner,key(),question(p))));assertEquals(409,code(()->cases.write(owner,id,"message",key(),follow(2,p))));cases.write(handlerA,id,"reply",key(),text(2,"跨月后仍处理已有留言"));assertEquals(2L,((Map<?,?>)cases.detail(owner,id,1).get("messages")).get("total"));
 }
 @Test void disabledPolicyVehicleOrOperatorImmediatelyPreventsNewUse(){
  eligible();long p=configure("AVAILABLE"),id=submit(p);cases.assign(manager,id,key(),assign(1,1001));jdbc.update("UPDATE operator_account SET can_diagnose=0 WHERE id=1001");assertEquals(403,code(()->cases.detail(handlerA,id,1)));assertEquals(403,code(()->cases.write(handlerA,id,"reply",key(),text(2,"不可回复"))));jdbc.update("UPDATE vehicle SET user_id=2 WHERE id=901");assertEquals(404,code(()->cases.write(owner,id,"message",key(),follow(2,p))));assertNotNull(cases.detail(owner,id,1));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->cases.detail(owner,id,1)));
 }
 @Test void eventAndAuditFailuresRollbackTextCaseAndSubmissionIntent(){
  eligible();long p=configure("AVAILABLE");String k=key();jdbc.execute("CREATE TRIGGER fail_diagnosis_event BEFORE INSERT ON diagnosis_case_event FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->cases.create(owner,k,question(p))));assertEquals(0,count("diagnosis_case"));assertEquals(0,count("diagnosis_message"));jdbc.execute("DROP TRIGGER fail_diagnosis_event");long id=cases.create(owner,k,question(p)).path("data").path("case_id").asLong();cases.assign(manager,id,key(),assign(1,1001));jdbc.execute("CREATE TRIGGER fail_diagnosis_event BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->cases.write(handlerA,id,"reply",key(),text(2,"不可部分保存"))));assertEquals(1,count("diagnosis_message"));assertEquals("PROCESSING",cases.row(id,false).get("status"));
 }
 @Test void concurrentAssignmentHasOneCasWinner()throws Exception{
  eligible();long p=configure("AVAILABLE"),id=submit(p);var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var jobs=new ArrayList<Future<Integer>>();for(long op:List.of(1001L,1002L))jobs.add(pool.submit(()->{start.await();try{cases.assign(manager,id,key(),assign(1,op));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var f:jobs)codes.add(f.get(30,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);assertEquals(2,count("diagnosis_case_event"));}finally{pool.shutdownNow();}
 }
 @Test void admissionAfterGuardWaitUsesCurrentDeadline()throws Exception{
  eligible();long p=configure("AVAILABLE");var pool=Executors.newSingleThreadExecutor();try(var connection=jdbc.getDataSource().getConnection()){connection.setAutoCommit(false);try(var stmt=connection.createStatement()){stmt.executeQuery("SELECT id FROM diagnosis_control WHERE id=1 FOR UPDATE");}var started=new CountDownLatch(1);var future=pool.submit(()->{started.countDown();try{cases.create(owner,key(),question(p));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});assertTrue(started.await(5,TimeUnit.SECONDS));var diagnostics=new org.springframework.jdbc.core.JdbcTemplate(new org.springframework.jdbc.datasource.DriverManagerDataSource(mysql.getJdbcUrl(),"root",mysql.getPassword()));boolean waiting=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<deadline){if(diagnostics.queryForList("SELECT trx_state,trx_query FROM information_schema.innodb_trx").stream().anyMatch(r->"LOCK WAIT".equals(r.get("trx_state"))&&String.valueOf(r.get("trx_query")).contains("diagnosis_control"))){waiting=true;break;}if(future.isDone())break;Thread.sleep(100);}assertTrue(waiting,"must observe actual diagnosis control lock wait");clock.value=clock.value.plusSeconds(3601);connection.commit();assertEquals(409,future.get(30,TimeUnit.SECONDS));assertEquals(0,count("diagnosis_case"));}finally{pool.shutdownNow();}
 }
 @Test void distinctManagersCannotPublishTwoActiveServiceVersions()throws Exception{
  long one=servicePolicy.save(operator,null,key(),config("AVAILABLE")).path("data").path("id").asLong(),two=servicePolicy.save(manager,null,key(),config("LEAVE_MESSAGE")).path("data").path("id").asLong();var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var jobs=new ArrayList<Future<Integer>>();for(var pair:List.of(new Object[]{operator,one},new Object[]{manager,two}))jobs.add(pool.submit(()->{start.await();try{servicePolicy.status((OperatorActor)pair[0],(Long)pair[1],key(),statusBody(1,"PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var f:jobs)codes.add(f.get(30,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);}finally{pool.shutdownNow();}
 }
 @Test void staleOwnerReadCannotAppendAfterPolicyStopsDuringGuardWait()throws Exception{
  eligible();long p=configure("AVAILABLE"),id=submit(p);var pool=Executors.newSingleThreadExecutor();try(var connection=jdbc.getDataSource().getConnection()){connection.setAutoCommit(false);try(var statement=connection.createStatement()){statement.executeQuery("SELECT id FROM diagnosis_control WHERE id=1 FOR UPDATE").close();}var future=pool.submit(()->{try{cases.write(owner,id,"message",key(),follow(1,p));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var monitor=new org.springframework.jdbc.core.JdbcTemplate(new org.springframework.jdbc.datasource.DriverManagerDataSource(mysql.getJdbcUrl(),"root",mysql.getPassword()));boolean waiting=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<deadline){if(monitor.queryForList("SELECT trx_state,trx_query FROM information_schema.innodb_trx").stream().anyMatch(r->"LOCK WAIT".equals(r.get("trx_state"))&&String.valueOf(r.get("trx_query")).contains("diagnosis_control"))){waiting=true;break;}if(future.isDone())break;Thread.sleep(100);}assertTrue(waiting);try(var stmt=connection.createStatement()){stmt.executeUpdate("UPDATE invite_diagnosis_policy SET status='STOPPED',revision=revision+1 WHERE status='PUBLISHED'");}connection.commit();assertEquals(409,future.get(30,TimeUnit.SECONDS));assertEquals(1,count("diagnosis_message"));}finally{pool.shutdownNow();}
 }
}
